"""Generate H1's complete ordinary-camp catalogue from sealed installed data."""
from pathlib import Path
import hashlib,json,math
ROOT=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 source=ROOT/'build/audit-v022/complete-jungle/manifest.json';r=json.loads(source.read_text(encoding='utf8'));assert r['complete']
 camps=[c for c in r['camps'] if int(c['NeutralType'])<3]
 names=sorted({s for c in camps for p in c['possible_combinations'] for s in p['entries'] if s});ids={s:i for i,s in enumerate(names)}
 count=[max(sum(bool(s) for s in p['entries']) for p in c['possible_combinations']) for c in camps]
 assert len(camps)==26 and len(names)==30 and sum(count)==96
 def number(d,k,scale=1,default=0):return int(math.floor(float(d.get(k,default))*scale+.5))
 fields=[('StatusHealth',1),('StatusMana',1),('AttackDamageMin',1),('ArmorPhysical',1),('AttackRange',1),('MovementSpeed',1),('AttackRate',20),('AttackAnimationPoint',1000),('BaseAttackSpeed',1),('ProjectileSpeed',1),('BountyGoldMin',1),('BountyGoldMax',1),('BountyXP',1),('AttackAcquisitionRange',1),('VisionDaytimeRange',1),('VisionNighttimeRange',1),('MagicalResistance',1),('StatusHealthRegen',100)]
 rows=[];records=[];native_rows=[]
 hulls={'DOTA_HULL_SIZE_SMALL':8,'DOTA_HULL_SIZE_REGULAR':16,'DOTA_HULL_SIZE_HERO':24,'DOTA_HULL_SIZE_HUGE':80}
 for name in names:
  u=r['units'][name];d=u['effective_stats_with_script_defaults'];values=[number(d,k,scale) for k,scale in fields]
  values[2]=(number(d,'AttackDamageMin')+number(d,'AttackDamageMax'))//2
  if d['AttackCapabilities']=='DOTA_UNIT_CAP_MELEE_ATTACK':values[9]=0
  hull=d.get('BoundsHullName','DOTA_HULL_SIZE_HERO');assert hull in hulls,(name,hull)
  values += [hulls[hull],128+ids[name]];assert all(-32768<=v<=32767 for v in values),(name,values)
  rows.append('    {'+','.join(map(str,values))+'}, /* '+name+' */')
  records.append(dict(id=ids[name],model_id=128+ids[name],name=name,source=u,stats=values))
  native=[number(d,k,scale) for k,scale in [('StatusMana',1),('StatusHealthRegen',100),('StatusManaRegen',100),('Level',1),('BountyXP',1),('BountyGoldMin',1),('BountyGoldMax',1),('MagicalResistance',1),('AttackRate',20),('AttackAnimationPoint',1000),('BaseAttackSpeed',1),('ProjectileSpeed',1)]]
  if d['AttackCapabilities']=='DOTA_UNIT_CAP_MELEE_ATTACK':native[-1]=0
  native_rows.append(' {'+','.join(map(str,native))+'}, /* '+name+' */')
 first=[];cursor=127
 for n in count:first.append(cursor);cursor+=n
 assert cursor==223 and cursor+32==255
 combinations=[]
 for cat in r['categories'][:3]:
  combinations.append('    {'+','.join('{'+','.join(str(ids.get(s,-1)) for s in p['entries'])+'}' for p in cat['subtypes'])+'}')
 positions=[(int(math.floor(c['world_xyz'][0]+.5)),int(math.floor(c['world_xyz'][1]+.5))) for c in camps]
 lo=[min(c['possible_subtype_indices']) for c in camps];hi=[max(c['possible_subtype_indices']) for c in camps]
 lines=['#ifndef H1_DOTA_JUNGLE_DATA_H','#define H1_DOTA_JUNGLE_DATA_H','/* Generated from original server category table and original map spawners. */','#define DOTA_JUNGLE_SPECIES 30','#define DOTA_JUNGLE_UNIT_SLOTS 96',
 'typedef struct {short hp,mana,damage,armor,range,speed,bat_ticks,point_ms,attack_speed,projectile_speed,gold_min,gold_max,xp,acquisition,vision_day,vision_night,magic_resist,regen100,hull,model;} DotaJungleDefinition;',
 'static const DotaJungleDefinition dota_jungle_definitions[30]={',*rows,'};',
 'static const unsigned char dota_jungle_levels[30]={'+','.join(str(number(r['units'][name]['effective_stats_with_script_defaults'],'Level')) for name in names)+'};',
 'static const unsigned char dota_jungle_camp_first[26]={'+','.join(map(str,first))+'};',
 'static const unsigned char dota_jungle_camp_capacity[26]={'+','.join(map(str,count))+'};',
 'static const unsigned char dota_jungle_camp_type[26]={'+','.join(c['NeutralType'] for c in camps)+'};',
 'static const unsigned char dota_jungle_camp_low[26]={'+','.join(map(str,lo))+'};',
 'static const unsigned char dota_jungle_camp_high[26]={'+','.join(map(str,hi))+'};',
 'static const signed char dota_jungle_combinations[3][7][5]={',',\n'.join(combinations),'};',
 '#define DOTA_JUNGLE_CAMP_POSITIONS '+','.join('{'+str(x)+','+str(y)+'}' for x,y in positions),'#endif','']
 target=ROOT/'game/jungle_data.h';target.write_text('\n'.join(lines),encoding='utf8')
 (ROOT/'game/jungle_npc_data.h').write_text('/* Generated by prepare_complete_jungle.py, using installed original units. */\nstatic const DotaNpcSourceDef jungle_npc_source[30]={\n'+'\n'.join(native_rows)+'\n};\nstatic const DotaNpcSourceDef *npc_definition(int id){return id>=17&&id<47?&jungle_npc_source[id-17]:&npc_source[id>0&&id<17?id:0];}\n',encoding='utf8')
 out=ROOT/'private/jungle-complete';out.mkdir(exist_ok=True)
 manifest=dict(complete=True,camps=camps,units=records,ordinary_camps=26,species=30,unit_slots=96,first_unit=127,item_unit_first=223,max_units=255,source_manifest_sha256=sha(source),generated_header_sha256=sha(target),generator_sha256=sha(__file__))
 (out/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print(json.dumps({k:manifest[k] for k in ('complete','ordinary_camps','species','unit_slots','max_units')}))
if __name__=='__main__':main()
